import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';
import { Comment } from '@/types/api';
import { useNotifications } from '@/components/ui/notifications';

import { getInfiniteCommentsQueryOptions } from './get-comments';

export const updateCommentInputSchema = z.object({
  body: z.string().min(1, 'Required'),
});

export type UpdateCommentInput = z.infer<typeof updateCommentInputSchema>;

export const updateComment = ({
  commentId,
  data,
}: {
  commentId: string;
  data: UpdateCommentInput;
}): Promise<Comment> => {
  return api.patch(`/comments/${commentId}`, data);
};

type UseUpdateCommentOptions = {
  discussionId: string;
  mutationConfig?: MutationConfig<typeof updateComment>;
};

export const useUpdateComment = ({
  mutationConfig,
  discussionId,
}: UseUpdateCommentOptions) => {
  const queryClient = useQueryClient();
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      addNotification({
        type: 'success',
        title: 'Comment Updated',
      });
      queryClient.invalidateQueries({
        queryKey: getInfiniteCommentsQueryOptions(discussionId).queryKey,
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateComment,
  });
};

import { Edit } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, FormDrawer, Textarea } from '@/components/ui/form';

import { useUpdateComment, updateCommentInputSchema } from '../api/update-comment';
import { Comment } from '@/types/api';

import { Authorization, POLICIES } from '@/lib/authorization';
import { useUser } from '@/lib/auth';

type EditCommentProps = {
  id: string;
  discussionId: string;
  comment: Comment;
};

export const EditComment = ({ id, discussionId, comment }: EditCommentProps) => {
  const user = useUser();
  const editCommentMutation = useUpdateComment({
    discussionId,
  });

  const canEdit = POLICIES['comment:update'](
    user.data as any,
    comment,
  );

  if (!canEdit) {
    return null;
  }

  return (
    <Authorization
      policyCheck={canEdit}
      forbiddenFallback={null}
    >
      <FormDrawer
        isDone={editCommentMutation.isSuccess}
        triggerButton={
          <Button
            variant="outline"
            size="sm"
            icon={<Edit className="size-4" />}
          >
            Edit Comment
          </Button>
        }
        title="Edit Comment"
        submitButton={
          <Button
            isLoading={editCommentMutation.isPending}
            form="edit-comment"
            type="submit"
            size="sm"
            disabled={editCommentMutation.isPending}
          >
            Submit
          </Button>
        }
      >
        <Form
          id="edit-comment"
          defaultValues={{
            body: comment.body,
          }}
          onSubmit={(values) => {
            editCommentMutation.mutate({
              commentId: id,
              data: values,
            });
          }}
          schema={updateCommentInputSchema}
        >
          {({ register, formState }) => (
            <Textarea
              label="Body"
              error={formState.errors['body']}
              registration={register('body')}
            />
          )}
        </Form>
      </FormDrawer>
    </Authorization>
  );
};

import * as React from 'react';

import { Comment, User } from '@/types/api';

import { useUser } from './auth';

export enum ROLES {
  ADMIN = 'ADMIN',
  USER = 'USER',
}

type RoleTypes = keyof typeof ROLES;

export const POLICIES = {
  'comment:delete': (user: User, comment: Comment) => {
    if (user.role === 'ADMIN') {
      return true;
    }

    if (user.role === 'USER' && comment.author?.id === user.id) {
      return true;
    }

    return false;
  },
  'comment:update': (user: User, comment: Comment) => {
    if (user.role === 'ADMIN') {
      return true;
    }

    if (user.role === 'USER' && comment.author?.id === user.id) {
      return true;
    }

    return false;
  },
};

export const useAuthorization = () => {
  const user = useUser();

  if (!user.data) {
    throw Error('User does not exist!');
  }

  const checkAccess = React.useCallback(
    ({ allowedRoles }: { allowedRoles: RoleTypes[] }) => {
      if (allowedRoles && allowedRoles.length > 0 && user.data) {
        return allowedRoles?.includes(user.data.role);
      }

      return true;
    },
    [user.data],
  );

  return { checkAccess, role: user.data.role };
};

type AuthorizationProps = {
  forbiddenFallback?: React.ReactNode;
  children: React.ReactNode;
} & (
  | {
      allowedRoles: RoleTypes[];
      policyCheck?: never;
    }
  | {
      allowedRoles?: never;
      policyCheck: boolean;
    }
);

export const Authorization = ({
  policyCheck,
  allowedRoles,
  forbiddenFallback = null,
  children,
}: AuthorizationProps) => {
  const { checkAccess } = useAuthorization();

  let canAccess = false;

  if (allowedRoles) {
    canAccess = checkAccess({ allowedRoles });
  }

  if (typeof policyCheck !== 'undefined') {
    canAccess = policyCheck;
  }

  return <>{canAccess ? children : forbiddenFallback}</>;
};
